    RETURN ELT(1 + FLOOR(RAND() * 20), 
        'Reyes', 'Ramirez', 'Rios', 'Rene', 'Perez', 'Cazarez', 'Barrios', 'Garcia', 
        'Hernandez', 'Lopez', 'Gonzalez', 'Martinez', 'Rodriguez', 'Sanchez', 
        'Martin', 'Gomez', 'Diaz', 'Torres', 'Vargas', 'Castro');
END ;;
