DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_bulk_insert_users`(
    IN p_quantity INT,
    IN p_domain VARCHAR(50)
)
BEGIN
    DECLARE v_counter INT DEFAULT 0;
    DECLARE v_username VARCHAR(50);
    DECLARE v_email VARCHAR(100);
    
    -- Optimización de rendimiento e integridad con transacciones
    START TRANSACTION;
    
    WHILE v_counter < p_quantity DO
        SET v_username = CONCAT('usr_', fn_generate_random_string(8));
        SET v_email = fn_generate_user_email(v_username, p_domain);
        
        INSERT INTO tb_users (username, email, created_at, status)
        VALUES (v_username, v_email, NOW(), 'ACTIVE');
        
        SET v_counter = v_counter + 1;
    END WHILE;
    
    COMMIT;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
