DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_productos_por_categoria`()
BEGIN
    SELECT ID, categoria, total_productos
    FROM (
        SELECT 
            c.ID AS ID,
            c.name AS categoria,
            COUNT(DISTINCT p.ID) AS total_productos,
            0 AS orden
        FROM tbc_categories c
        LEFT JOIN tbd_products_categories pc ON c.ID = pc.category_ID
        LEFT JOIN tb_products p ON pc.product_ID = p.ID
        GROUP BY c.ID, c.name

        UNION ALL

        SELECT 
            NULL AS ID,
            'Sin categoría' AS categoria,
            COUNT(DISTINCT p.ID) AS total_productos,
            1 AS orden
        FROM tb_products p
        LEFT JOIN tbd_products_categories pc ON p.ID = pc.product_ID
        WHERE pc.product_ID IS NULL
    ) AS reporte
    ORDER BY orden ASC, ID ASC;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
